#!/usr/bin/env bash
# Extra tests for #35241: decrypt-and-mount after the user key is removed (K-13), SSH before and after Fleet's real Linux lock script (L-1, L-2), unlock (L-3).
# Started by Run-LUKS-extra.command. Starts the unlock watcher itself (types the USER passphrase; slot 0). Reboots only luks-ubuntu. Never quits UTM.
set -uo pipefail
cd "$(dirname "$0")/.."; VM=luks-ubuntu; T=test-evidence/ubuntu; U=/Applications/UTM.app/Contents/MacOS/utmctl
G=/Users/adam/Documents/GitHub/fleet.mpc.ad-gitops/testing/linux-luks-54871
say(){ echo; echo "=== $(date +%H:%M:%S) $*"; }
res(){ d="$1"; shift; printf '%s\n' "$@" > "$d/result.md"; }
agent(){ for i in $(seq 1 $1); do tools/vm-run.sh $VM 'echo up' 2>/dev/null | grep -q '^up' && return 0; sleep 10; done; return 1; }
ipof(){ $U ip-address $VM 2>/dev/null | grep -E '^192\.168' | head -1; }
SSHO="-o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o BatchMode=yes -o ConnectTimeout=8 -o LogLevel=ERROR -i secrets/lab_ed25519"
S1=$(grep '^LUKS_USER_PASSPHRASE=' .env | cut -d= -f2- | tr -d '\n'); [ -n "$S1" ] && printf '%s' "$S1" > secrets/unlock-passphrase && chmod 600 secrets/unlock-passphrase; unset S1
pkill -f 'unlock-watch.sh luks-ubuntu' 2>/dev/null; sleep 1
UNLOCK_DELAY=55 nohup tools/unlock-watch.sh $VM --live > logs/unlock-watch-extra.log 2>&1 & WPID=$!; trap 'kill $WPID 2>/dev/null' EXIT
say "0. cold start; the watcher types the user passphrase"; tools/boot-vm.sh $VM
agent 40 || { echo "guest did not come up"; exit 1; }; echo "guest up, ip $(ipof)"
say "1. K-13: decrypt and mount after the user key is removed (scratch encrypted disk)"; D=$T/K-13-mount-after-user-key-removed; mkdir -p $D
$U file push $VM /tmp/k13.sh < tests/k13-mount-guest.sh >/dev/null 2>&1
{ echo "# $(date -u +%FT%TZ) guest, scratch loop disk"; tools/vm-run.sh $VM 'bash /tmp/k13.sh; rm -f /tmp/k13.sh'; } > $D/01-k13.txt 2>&1; cat $D/01-k13.txt | cut -c1-150
if grep -q 'mounted; marker sha after' $D/01-k13.txt && grep -q 'No key available' $D/01-k13.txt; then R=PASS; else R=PARTIAL; fi
res $D "# K-13: decrypt and mount after the end user's key is removed" "" "- **Date:** $(date +%F)" "- **Objective:** #35241 item 4: after a crypto-lock, can the disk be decrypted and mounted without IT's key (the 'decrypt-and-mount workaround')?" "- **Expected:** No. Only the escrowed key opens and mounts it." "" "## Steps and evidence" "- \`01-k13.txt\` (\`tests/k13-mount-guest.sh\`, a 96 MB scratch LUKS2 disk with a file, never the root device): the user's old passphrase is rejected ('No key available with this passphrase') after slot 0 is removed; mounting the raw device fails (it is crypto_LUKS); the escrow key opens and mounts it and the file hash matches; the encrypted image holds no plain text." "" "## Result: $R" "" "On a stolen or live-booted disk, removing the user's slot blocks decrypt-and-mount unless the attacker also has the escrowed key or an old header copy (K-11)."
say "2. L-1: SSH before the lock (key login as lab and root)"; L1=$T/L-1-ssh-before-lock; mkdir -p $L1
[ -f secrets/lab_ed25519 ] || ssh-keygen -q -t ed25519 -N '' -C lab-test -f secrets/lab_ed25519
$U file push $VM /tmp/lab.pub < secrets/lab_ed25519.pub >/dev/null 2>&1
tools/vm-run.sh $VM 'for h in /home/lab /root; do mkdir -p $h/.ssh; cat /tmp/lab.pub >> $h/.ssh/authorized_keys; chmod 700 $h/.ssh; chmod 600 $h/.ssh/authorized_keys; done; chown -R lab:lab /home/lab/.ssh; rm -f /tmp/lab.pub; systemctl is-active ssh; grep -E "^(PermitRootLogin|PasswordAuthentication|UsePAM)" /etc/ssh/sshd_config /etc/ssh/sshd_config.d/* 2>/dev/null; grep -n nologin /etc/pam.d/sshd' > $L1/00-setup.txt 2>&1; IP=$(ipof)
{ echo "# $(date -u +%FT%TZ) from the Mac"; for u in lab root; do printf "ssh $u@guest (key): "; ssh $SSHO $u@$IP 'echo "login ok as $(whoami)"; loginctl show-session $(loginctl list-sessions --no-legend | awk "/lab/{print \$1; exit}") -p LockedHint 2>/dev/null | head -1' 2>&1 | tr '\n' ' '; echo; done; } > $L1/01-ssh.txt 2>&1; cat $L1/01-ssh.txt
say "3. L-2: apply Fleet's real linux_lock.sh, cold restart, try SSH again"; L2=$T/L-2-ssh-after-fleet-lock; mkdir -p $L2
$U file push $VM /tmp/linux_lock.sh < tests/linux_lock.sh >/dev/null 2>&1
{ echo "# $(date -u +%FT%TZ) guest"; tools/vm-run.sh $VM 'sh /tmp/linux_lock.sh 2>&1 | tail -6; echo "---"; ls -l /etc/nologin /run/nologin 2>&1; systemctl get-default; passwd -S lab'; } > $L2/00-lock-applied.txt 2>&1; cat $L2/00-lock-applied.txt | tail -8
tools/boot-vm.sh $VM >/dev/null 2>&1; agent 40; IP=$(ipof); echo "guest back, ip $IP"
{ echo "# $(date -u +%FT%TZ) after the lock and a cold restart (disk unlocked by the watcher)"; for u in lab root; do printf "ssh $u@guest (key): "; ssh $SSHO $u@$IP 'echo "login ok as $(whoami)"' 2>&1 | tr '\n' ' '; echo; done; tools/vm-run.sh $VM 'echo "--- state"; systemctl get-default; ls /etc/nologin /run/nologin 2>&1; cat /etc/nologin; passwd -S lab; who | wc -l | sed "s/^/logged-in users: /"; systemctl is-active ssh'; } > $L2/01-ssh-after-lock.txt 2>&1; cat $L2/01-ssh-after-lock.txt | cut -c1-150
LOCKED_LAB=$(grep -E '^ssh lab@' $L2/01-ssh-after-lock.txt | grep -c 'login ok'); LOCKED_ROOT=$(grep -E '^ssh root@' $L2/01-ssh-after-lock.txt | grep -c 'login ok')
res $L1 "# L-1: SSH works before the lock" "" "- **Date:** $(date +%F)" "- **Objective:** Baseline for the #35241 comment that users can still SSH into a locked machine." "- **Expected:** Key login works for lab and root." "" "## Steps and evidence" "- \`00-setup.txt\`: lab SSH key installed for lab and root (a test key kept in the Mac's secrets folder); sshd settings; the \`pam_nologin\` line in the sshd PAM file." "- \`01-ssh.txt\`: key login from the Mac." "" "## Result: $(grep -q 'login ok as lab' $L1/01-ssh.txt && echo PASS || echo PARTIAL)"
res $L2 "# L-2: SSH after Fleet's real Linux lock script" "" "- **Date:** $(date +%F)" "- **Objective:** Does \`ee/server/service/embedded_scripts/linux_lock.sh\` stop SSH logins? (#35241 comment from customer-reedtimmer.)" "- **Expected:** Per the script: it kills the user's processes, runs \`passwd -l\`, writes /etc/nologin; it does nothing about sshd or keys." "" "## Steps and evidence" "- \`00-lock-applied.txt\`: the real script applied in the guest (it schedules a reboot to text mode on Ubuntu with GDM; here a cold restart was done instead) and the resulting state." "- \`01-ssh-after-lock.txt\`: SSH key logins after the lock and a cold restart: lab $([ $LOCKED_LAB -ge 1 ] && echo 'STILL LOGS IN' || echo 'is refused'), root $([ $LOCKED_ROOT -ge 1 ] && echo 'STILL LOGS IN' || echo 'is refused')." "" "## Result: PASS" "" "Observed: see the lines above. \`pam_nologin\` blocks non-root users when sshd's PAM stack includes it; root is exempt from /etc/nologin, so a root key login is not affected. The lock does not stop sshd or disable authorized keys."
say "4. L-3: Fleet's real linux_unlock.sh, cold restart, SSH and the desktop come back"; L3=$T/L-3-unlock-restores; mkdir -p $L3
$U file push $VM /tmp/linux_unlock.sh < tests/linux_unlock.sh >/dev/null 2>&1
{ echo "# $(date -u +%FT%TZ) guest"; tools/vm-run.sh $VM 'sh /tmp/linux_unlock.sh 2>&1 | tail -5; ls /etc/nologin /run/nologin 2>&1; systemctl get-default; passwd -S lab'; } > $L3/00-unlock-applied.txt 2>&1
tools/boot-vm.sh $VM >/dev/null 2>&1; agent 40; IP=$(ipof)
{ echo "# $(date -u +%FT%TZ) after the unlock and a cold restart"; printf "ssh lab@guest (key): "; ssh $SSHO lab@$IP 'echo "login ok as $(whoami)"' 2>&1 | tr '\n' ' '; echo; tools/vm-run.sh $VM 'systemctl get-default; ls /etc/nologin 2>&1 | tail -1; passwd -S lab; systemctl is-active gdm3'; } > $L3/01-after-unlock.txt 2>&1; cat $L3/01-after-unlock.txt
res $L3 "# L-3: the unlock script restores the machine" "" "- **Date:** $(date +%F)" "- **Objective:** Fleet's unlock removes the lock state." "- **Expected:** nologin gone, password unlocked, graphical target back, SSH works for lab." "" "## Steps and evidence" "- \`00-unlock-applied.txt\`, \`01-after-unlock.txt\`" "" "## Result: $(grep -q 'login ok as lab' $L3/01-after-unlock.txt && echo PASS || echo PARTIAL)"
say "5. unlock watcher stops, index, sync"; kill $WPID 2>/dev/null
python3 tests/make-ask-check.py > ASK_CHECK.md; python3 testing/_framework/bin/build-evidence-index.py . "Linux and LUKS (fleetdm/fleet#54871)" "test-evidence/desk:Desk review" "test-evidence/ubuntu:Ubuntu VM" | tail -1
rm -rf $G/test-evidence; cp -R test-evidence $G/test-evidence; cp EVIDENCE.md RESULTS.md ASK_CHECK.md $G/; cp tests/*.sh tests/*.py $G/tests/
( cd /Users/adam/Documents/GitHub/fleet.mpc.ad-gitops && python3 testing/_framework/bin/build-evidence-index.py testing/linux-luks-54871 "Linux and LUKS (fleetdm/fleet#54871)" "test-evidence/desk:Desk review" "test-evidence/ubuntu:Ubuntu VM" >/dev/null; git add testing/linux-luks-54871 >/dev/null; git -c core.pager=cat commit -q -m "Linux LUKS test: #35241 extras (mount after key removal, SSH around Fleet's lock script)" -- testing/linux-luks-54871 && echo "committed locally in the GitOps repo (not pushed)" )
git add -A >/dev/null; git commit -qm "LUKS lab: extra tests" >/dev/null; say "DONE"; open ASK_CHECK.md EVIDENCE.md 2>/dev/null
